<template><div class="page-container"><div class="page-header"><div><h2>教职工工作计划与协同</h2><p>周月计划、任务指派与负责人点评</p></div><div><el-input-number v-model="userId" :min="1"/><el-button @click="loadMine">我的计划</el-button><el-button @click="loadAll">全部计划</el-button><el-button type="primary" @click="openCreate">新建/指派</el-button></div></div>
<el-row :gutter="16"><el-col v-for="row in rows" :key="row.planId" :span="8"><el-card class="plan-card" shadow="hover"><template #header><div class="card-title"><b>{{ row.planType }}</b><el-tag :type="row.status===2?'success':'primary'">{{ row.status===2?'已完成':'进行中' }}</el-tag></div></template><p class="content">{{ row.content }}</p><p class="muted">负责人：{{ row.userId }} · {{ row.startDate }} 至 {{ row.endDate }}</p><el-alert v-if="row.supervisorComment" :title="`上级点评：${row.supervisorComment}`" type="info" :closable="false"/><div class="actions"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link @click="comment(row)">点评</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></div></el-card></el-col></el-row>
<el-empty v-if="!rows.length" description="暂无工作计划"/><el-dialog v-model="visible" title="工作计划/任务指派" width="560"><el-form label-width="90"><el-form-item label="执行人ID"><el-input-number v-model="form.userId" :min="1"/></el-form-item><el-form-item label="计划类型"><el-radio-group v-model="form.planType"><el-radio-button value="周计划">周计划</el-radio-button><el-radio-button value="月计划">月计划</el-radio-button></el-radio-group></el-form-item><el-form-item label="计划内容"><el-input v-model="form.content" type="textarea" :rows="5"/></el-form-item><el-form-item label="起止日期"><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="进行中" :value="1"/><el-option label="已完成" :value="2"/></el-select></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{workPlanAPI}from'@/api/getData.js';const userId=ref(1),rows=ref([]),visible=ref(false),dateRange=ref([]),form=reactive({planId:null,userId:1,planType:'周计划',content:'',status:1});const loadMine=async()=>{const r=await workPlanAPI.getUserPlans(userId.value);if(r&&r!==-1)rows.value=r.data||[]};const loadAll=async()=>{const r=await workPlanAPI.list();if(r&&r!==-1)rows.value=r.data||[]};const openCreate=()=>{Object.assign(form,{planId:null,userId:userId.value,planType:'周计划',content:'',status:1});dateRange.value=[];visible.value=true};const edit=row=>{Object.assign(form,row);dateRange.value=[row.startDate,row.endDate];visible.value=true};const save=async()=>{const r=await workPlanAPI.save({...form,startDate:dateRange.value?.[0],endDate:dateRange.value?.[1]});if(r&&r!==-1){ElMessage.success('计划已保存');visible.value=false;loadMine()}};const comment=async row=>{const{value}=await ElMessageBox.prompt('请输入负责人点评','计划点评',{inputValue:row.supervisorComment||''});const r=await workPlanAPI.comment(row.planId,value);if(r&&r!==-1){ElMessage.success('点评成功');loadAll()}};const remove=async row=>{await ElMessageBox.confirm('确认删除？','提示');const r=await workPlanAPI.remove(row.planId);if(r&&r!==-1)loadMine()};onMounted(loadMine);</script>
<style scoped>.page-container{padding:24px;background:#f5f7fa;min-height:100vh}.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.page-header h2{margin:0}.page-header p,.muted{color:#909399}.page-header>div:last-child{display:flex;gap:8px}.plan-card{margin-bottom:16px}.card-title{display:flex;justify-content:space-between}.content{min-height:52px;white-space:pre-wrap}.actions{text-align:right;margin-top:12px}</style>
